import java.util.Scanner;

public class Main {
    static final long P = 1000000007L;

    static long power(long a, int n) {
        long t = 1;
        while (n > 0) {
            if ((n & 1) == 1) {
                t = (t * a) % P;
            }
            a = (a * a) % P;
            n >>= 1;
        }
        return t;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();

        if (k == 0) {
            System.out.println(power(p, p - 1));
            return;
        }
        if (k == 1) {
            System.out.println(power(p, p));
            return;
        }

        boolean[] vis = new boolean[1000020];
        vis[1] = true;
        int len = 1;
        long i = k;
        while (!vis[(int) i]) {
            vis[(int) i] = true;
            i = (i * k) % p;
            len++;
        }
        int tot = (p - 1) / len;
        System.out.println(power(p, tot));
    }
}
